end
function M.fmt(sb)
sb=tonumber(sb)or 0
if sb>=1e6 then
return string.format(Tyc[1500],sb/1e6)
end
if sb>=1e4 then
return string.format(Tyc[1501],sb/1e3)
end
return tostring(math.floor(sb+0.5))
end
function M.clamp(tb,ub,vb)
return math.max(ub,math.min(vb,tb))
end
function M.count(wb)
local xb=0
for yb in pairs(wb or{})do
xb=xb+1
end
return xb
end
function M.list(zb)
if type(zb)~=Tyc[1502]then
return{}
end
if#zb>0 then
return zb
end
local Ab={}
for Bb in pairs(zb)do
table.insert(Ab,Bb)
end
table.sort(Ab,function(Cb,Db)
return(tonumber(Cb)or 0)<(tonumber(Db)or 0)
end)
local Eb={}
for Fb,Gb in ipairs(Ab)do
table.insert(Eb,zb[Gb])
end
return Eb
end
