return Vector3 .new(Hb.X,0,Hb.Z)
end
function M.plain(Ib,Jb)
local Kb=type(Ib)
if Kb==Tyc[1503]or Kb==Tyc[1504]or Kb==Tyc[1505]then
return Ib
end
if Kb~=Tyc[1502]or(Jb or 0)>6 then
return nil
end
local Lb={}
for Mb,Nb in pairs(Ib)do
if type(Mb)==Tyc[1503]or type(Mb)==Tyc[1504]then
Lb[Mb]=M.plain(Nb,(Jb or 0)+1)
end
end
return Lb
end
