end
for wp,yp in pairs(lp.usage and lp.usage.possible_rewards or{})do
local zp=yp.unit or yp.item
if zp and H.Units[zp]and H.Units[zp].rarity==Tyc[1762]and not rp[zp]then
table.insert(pp.units,N.name(zp))
end
end
table.sort(pp.units)
