function db.gainXp(zK,AK)
local BK,CK=tonumber(zK.xp)or 0,db.xpFor(zK.unit_id,db.cap(zK))
local DK=math.max(0,CK-BK)
if DK<=0 or(AK or 0)<=0 then
return 0,0
end
local EK=math.min(AK,DK)
local FK=db.base(zK)
if FK<=0 then
return 0,EK
end
return db.share(zK.unit_id)*(db.score(db.whatIf(zK,{xp=BK+EK}))/FK-1)*100,EK
end
function db.gainFuse(GK)
if db.lb(GK)>=1 then
return 0
end
local HK=db.base(GK)
if HK<=0 then
return 0
end
local IK=db.whatIf(GK,{xp=math.max(tonumber(GK.xp)or 0,db.xpFor(GK.unit_id,110)),further_modifiers={limit_break={current_limit_break=1}}})
return db.share(GK.unit_id)*(db.score(IK)/HK-1)*100+5
end
