function db.relicWorth(JK,KK)
local LK=KK._unique_item_data and KK._unique_item_data._unique_relic_data
if not LK then
return 0
end
local MK=H.Items[KK.item_id]or{}
local NK,OK=N.types(JK.unit_id)
if MK.main_damage_type and MK.main_damage_type~=Tyc[2123]and MK.main_damage_type~=OK then
return 0
end
local PK,QK=0,0
for RK,SK in pairs(LK._core_damage_type_buffs or{})do
if NK[SK.damage_type]then
PK=PK+(tonumber(SK.mul)or 0)+(tonumber(SK.add_upg)or 0)*0.01+(tonumber(SK.pen)or 0)*0.001
QK=QK+(tonumber(SK.crit)or 0)
end
end
PK=PK+QK*0.5
local TK=N.rows(JK.unit_id)
local UK=TK and TK[TK.max]
local VK=(UK and tonumber(UK.cd)or 0)*N.mult(JK,Tyc[1637])
for WK,XK in pairs(LK._unique_relic_effects or{})do
local YK=type(XK.params)==Tyc[1502]and XK.params or{}
if XK.id==Tyc[2124]then
local ZK=math.min(1,(tonumber(YK.extra_damage)or 0)*VK/math.max(1,tonumber(YK.time_interval)or 40))
local _K=N.DRONES and N.DRONES[JK.unit_id]
if _K and _K.late and VK>0 then
local aL=1/VK
ZK=ZK*aL/(aL+(tonumber(_K.max)or 0)*(tonumber(_K.late.dmg)or 0)*(tonumber(_K.hits)or 1)/math.max(0.1,tonumber(_K.late.cd)or 4))
end
PK=PK+ZK
elseif XK.id==Tyc[2125]then
PK=PK+(tonumber(YK.dmg_buff)or 0)*0.25
elseif XK.id==Tyc[2126]then
PK=PK+(tonumber(YK.dmg_buff)or 0)*QK
elseif XK.id==Tyc[2127]then
if NK.magic then
PK=0
else
PK=PK+(tonumber(YK.dmg_buff)or 0)*0.3
end
elseif XK.id==Tyc[2128]then
if NK.water_damage then
PK=PK+0.05
end
end
end
return PK
end
