return
end
local IL=gL[GL]
CL[IL.e.uuid]=nil
FL(GL+1,HL)
for JL,KL in ipairs(IL.opts)do
local LL=(H.Items[KL.it.item_id]or{}).unique_equip
if not DL[KL.it.uuid]and not(LL and EL[KL.it.item_id])then
DL[KL.it.uuid]=true
if LL then
EL[KL.it.item_id]=true
end
CL[IL.e.uuid]=KL.it.uuid
FL(GL+1,HL+KL.w+(KL.it.uuid==IL.e.u._equipped_relic and 0.01 or 0))
CL[IL.e.uuid]=nil
DL[KL.it.uuid]=nil
if LL then
EL[KL.it.item_id]=nil
end
end
end
end
FL(1,0)
local ML,NL=0,{}
for OL,PL in ipairs(gL)do
local QL=PL.e.u._equipped_relic and bL.inventory:get_item_by_uuid(PL.e.u._equipped_relic)
local RL=QL and db.relicWorth(PL.e.u,QL)*PL.share*100 or 0
ML=ML+RL
local SL=AL[PL.e.uuid]and bL.inventory:get_item_by_uuid(AL[PL.e.uuid])
local TL=SL and db.relicWorth(PL.e.u,SL)*PL.share*100 or 0
table.insert(NL,string.format(Tyc[2131],N.name(PL.e.id),QL and(H.Items[QL.item_id]or{}).name or Tyc[1772],RL,SL and(H.Items[SL.item_id]or{}).name or Tyc[1772],TL))
end
return AL,BL-ML,NL,gL
end
