function P.fuseFuel(YQ,ZQ)
local _Q=H.session()
local aR={[YQ.uuid]=true,[I.evolveUnit]=true,[I.fuseXpUnit]=true}
local bR={}
for cR,dR in ipairs(N.equipped())do
aR[dR.uuid]=true
end
for eR,fR in ipairs(J.savedTeam or{})do
aR[fR]=true
end
for gR,hR in ipairs(J.train and J.train.on and J.train.on.base or{})do
aR[hR]=true
end
for iR,jR in ipairs(J.goals or{})do
aR[jR.uuid]=true
for kR,lR in ipairs(jR.eats or{})do
bR[lR.id]=true
end
end
for mR,nR in ipairs(J.str and J.str.core or{})do
aR[nR]=true
end
local oR=ab.strongest(10)
local pR,qR={},0
for rR,sR in pairs(_Q.profile_data.collection.owned_units)do
local tR=_Q.collection:get_unit_by_uuid(rR)or sR
local uR,vR,wR=pcall(H.USC.is_unit_good_for_fusion,YQ,tR)
if uR and vR and not(sR._locked or tR._locked)and not aR[rR]and not bR[tR.unit_id]and not(sR._equipped_relic or tR._equipped_relic)and not(sR.shiny or tR.shiny)and not N.trait(tR)and not(sR.further_modifiers and sR.further_modifiers.limit_break)then
local xR=ab.fodderOrder(tR.unit_id)
if xR and not oR[rR]then
local yR,zR=pcall(N.score,tR)
table.insert(pR,{uuid=rR,id=tR.unit_id,pts=tonumber(wR)or 1,sc=yR and zR or 0,order=xR})
qR=qR+(tonumber(wR)or 1)
end
end
end
table.sort(pR,function(AR,BR)
if AR.order~=BR.order then
return AR.order<BR.order
end
if AR.sc~=BR.sc then
return AR.sc<BR.sc
end
return AR.uuid<BR.uuid
end)
local CR,DR={},0
for ER,FR in ipairs(pR)do
if DR>=ZQ then
break
end
table.insert(CR,FR)
DR=DR+FR.pts
end
return CR,DR,qR
end
function P.fodderRows(GR)
