if _R~=GR.uuid and not IR[_R]and not aS._locked then
local bS=HR.collection:get_unit_by_uuid(_R)or aS
local cS,dS,eS=pcall(H.USC.is_unit_good_for_fusion,GR,bS)
if cS and dS and not bS._locked then
local fS=H.Units[bS.unit_id]or{}
local gS={}
