if KR[_R]or LR[bS.unit_id]then
table.insert(gS,Tyc[2244])
end
local jS,kS=pcall(N.score,bS)
table.insert(ZR,{uuid=_R,id=bS.unit_id,name=N.name(bS.unit_id),rarity=fS.rarity or Tyc[1740],lvl=db.level(bS),pts=tonumber(eS)or 1,evolved=N.isEvolvedForm(bS.unit_id),flags=gS,safe=UR[_R]or false,sc=jS and kS or 0})
end
end
end
table.sort(ZR,function(lS,mS)
if lS.safe~=mS.safe then
return lS.safe
end
if lS.sc~=mS.sc then
return lS.sc<mS.sc
end
return lS.uuid<mS.uuid
end)
return ZR
end
