local _9=(Y9 .cd>0 and Y9 .damage/Y9 .cd or 0)*N.aoe(Y9 .atk,Y9 .range)/math.max(0.3,N.aoe(X9 .atk,X9 .range))
local aab=Z9>0 and R9*(_9/Z9-1)or(W9 or 0)
local bab=S9[T9+2]
if bab and T9+1<S9 .max and bab.cd>0 and Y9 .cd>0 and Z9>0 then
local cab=R9*((bab.damage/bab.cd)/Z9-1)
local dab=U9+bab.cost*V9
if cab/dab>aab/U9 then
aab=aab+(cab/dab*U9-aab)*0.5
end
end
local eab=(Y9 .range or 0)>(X9 .range or 0)and(1+((Y9 .range-X9 .range)/math.max(1,X9 .range)))or 1
return math.max(0,aab)*eab
end
function V.dpsFor(fab,gab)
if gab<=0 then
return 0
end
local hab={}
for iab,jab in ipairs(fab)do
if not jab.farm and jab.gain>0 then
table.insert(hab,jab)
end
end
table.sort(hab,function(kab,lab)
return kab.gain/kab.cost>lab.gain/lab.cost
end)
local mab,nab=0,0
for oab,pab in ipairs(hab)do
if gab<=0 then
break
end
nab=pab.gain/pab.cost
local qab=math.min(1,gab/pab.cost)
mab=mab+pab.gain*qab
gab=gab-pab.cost*qab
end
return mab+math.max(0,gab)*nab*0.7
end
function V.shieldDps(rab,sab,tab,uab,vab,wab,xab)
if(uab or 0)<=0 or(rab or 0)<=0 or(vab or 0)<=0 then
return rab or 0
end
sab,tab,wab=math.max(0.3,sab or 2),math.max(1,tab or 1),wab or 1
local yab=rab*wab*sab/tab
return vab*tab/((uab/math.max(1,xab or 1)+math.max(1,vab/yab))*sab)/wab
end
function V.shieldGain(zab,Aab,Bab,Cab,Dab,Eab,Fab,Gab)
local Hab,Iab=N.attackInfo(Aab.atk,Aab.range),N.attackInfo(Cab.atk,Cab.range)
local Jab=V.shieldDps(zab,(tonumber(Aab.cd)or 2)*(Fab or 1),Hab.n,Dab,Eab,Gab,Hab.hits)
local Kab=V.shieldDps(Bab,(tonumber(Cab.cd)or 2)*(Fab or 1),Iab.n,Dab,Eab,Gab,Iab.hits)
local Lab=math.max(0,((tonumber(Cab.range)or 0)-(tonumber(Aab.range)or 0))/math.max(1,tonumber(Aab.range)or 1))
return math.max(0,Kab-Jab)+Jab*Lab
end
function V.shieldWork(Mab,Nab,Oab,Pab,Qab,Rab,Sab,Uab,Vab)
if(Pab or 0)<=0 then
return 0
end
local Wab=3*Pab*(Qab or 1)/math.max(1,Rab or 20)
if(Oab or 0)>=Wab then
return 0
end
return math.max(1,Mab or 1)*math.max(1,Vab or 1)/math.max(0.3,Nab or 2)*math.min(Sab or 0,Uab or 0)
