function W.evaluate(rpb,spb)
local tpb=W.run(rpb,spb,{hpMul=1})
local upb={won=tpb.won,wave=tpb.wave,minutes=tpb.t/60,aliveAt=tpb.aliveAt,total=rpb.total,at=os.time()}
if rpb.infinite and W.unbound(rpb.ld)then
upb.p=1
upb.margin=tpb.won and string.format(Tyc[2733],rpb.total)or string.format(Tyc[2734],tpb.wave,tpb.t/60)
elseif tpb.won then
local vpb=W.run(rpb,spb,{hpMul=1.3})
upb.p=vpb.won and 0.92 or 0.7
upb.margin=vpb.won and Tyc[2735]or Tyc[2736]
else
local wpb=W.run(rpb,spb,{hpMul=0.75})
upb.p=wpb.won and 0.25 or 0.05
upb.margin=wpb.won and string.format(Tyc[2737],tpb.wave)or string.format(Tyc[2738],tpb.wave,rpb.total)
if not wpb.won then
local xpb=W.run(rpb,spb,{hpMul=0.25})
if not xpb.won then
upb.p,upb.hopeless=0.005,true
upb.margin=string.format(Tyc[2739],tpb.wave,rpb.total)
end
end
end
return upb
end
W.STYLE_RUNS=20
function W.styleP(ypb,zpb)
local Apb=tonumber(ypb and ypb.p)or 0
if Apb<0.5 then
return Apb
end
zpb=zpb or((ypb.zone or ypb.style==Tyc[2722])and Tyc[2722]or Tyc[2740])
local Bpb,Cpb=pcall(U.hiveStyle,zpb)
if not(Bpb and Cpb)then
return Apb
end
local Dpb=tonumber(Cpb.predWin)or 0
local Epb=M.clamp((tonumber(Cpb.predWinWon)or 0)/math.max(1,Dpb),0,1)
local Fpb=Dpb/(Dpb+W.STYLE_RUNS)
return Apb*(1-Fpb*(1-Epb))
end
