table.insert(Bqb,Eqb[Jqb])
end
for Kqb=1,math.min(3,#sqb)do
table.insert(Bqb,sqb[Kqb].u)
end
local Lqb={}
for Mqb=11,#rqb do
local Nqb=N.rows(rqb[Mqb].u.unit_id)[0]
local Oqb=Nqb and Nqb.atk and N.attackInfo(Nqb.atk,Nqb.range)
