local Ywb=Xwb[0]or Xwb[Tyc[2804]]
return type(Ywb)==Tyc[1502]and Ywb.id or nil
end
function cb.fx(Zwb,_wb,axb)
local bxb={dmg=1,cd=1,range=1,cost=1,hp=1,speed=1,regen=0,crit=0,kinds={},shield=0,fly=0}
local cxb=cb.items(Zwb)
if _wb and cb.item(_wb)then
cxb[_wb]=(cxb[_wb]or 0)+1
end
if axb and cb.item(axb)then
cxb[axb]=(cxb[axb]or 0)+1
end
for dxb,exb in pairs(cxb)do
local fxb=cb.item(dxb)
for gxb,hxb in pairs(type(fxb and fxb.wave_modifier_effects)==Tyc[1502]and fxb.wave_modifier_effects or{})do
local ixb=(tonumber(hxb.amount)or 0)*exb
if hxb.type==Tyc[2793]and hxb.stat==Tyc[1636]then
bxb.dmg=bxb.dmg+ixb
elseif hxb.type==Tyc[2793]and hxb.stat==Tyc[1637]then
bxb.cd=bxb.cd+ixb
elseif hxb.type==Tyc[2793]and hxb.stat==Tyc[1639]then
bxb.range=bxb.range+ixb
elseif hxb.type==Tyc[2794]and tostring(hxb.stat):sub(1,9)==Tyc[2805]then
local jxb=tostring(hxb.stat):sub(10)
bxb.kinds[jxb]=(bxb.kinds[jxb]or 0)+ixb
elseif hxb.type==Tyc[2798]and hxb.stat==Tyc[2799]then
bxb.crit=bxb.crit+ixb
elseif hxb.type==Tyc[2802]then
bxb.cost=bxb.cost+ixb
elseif hxb.type==Tyc[2806]and hxb.stat==Tyc[2579]then
bxb.hp=bxb.hp+ixb
elseif hxb.type==Tyc[2801]then
bxb.speed=bxb.speed+ixb
elseif hxb.type==Tyc[2807]then
bxb.regen=bxb.regen+ixb
elseif hxb.type==Tyc[2808]then
bxb.shield=bxb.shield+ixb
elseif hxb.type==Tyc[2809]and hxb.passive==Tyc[2810]then
bxb.fly=bxb.fly+ixb
end
end
end
bxb.cd,bxb.cost,bxb.speed=math.max(0.1,bxb.cd),math.max(0.1,bxb.cost),math.max(0.1,bxb.speed)
return bxb
end
function cb.fxText(kxb)
local lxb={}
local function mxb(nxb,oxb)
if math.abs(oxb-1)>0.001 then
table.insert(lxb,string.format(Tyc[2811],nxb,oxb))
end
end
mxb(Tyc[1636],kxb.dmg)
mxb(Tyc[1897],kxb.cd)
mxb(Tyc[1639],kxb.range)
mxb(Tyc[2812],kxb.cost)
for pxb,qxb in pairs(kxb.kinds)do
table.insert(lxb,string.format(Tyc[1720],pxb,math.floor(qxb*100+0.5)))
end
if kxb.crit>0 then
table.insert(lxb,string.format(Tyc[2813],math.floor(kxb.crit*100+0.5)))
end
mxb(Tyc[2814],kxb.hp)
mxb(Tyc[2815],kxb.speed)
if kxb.regen>0 then
table.insert(lxb,string.format(Tyc[2816],math.floor(kxb.regen*100+0.5)))
end
if kxb.shield>0 then
table.insert(lxb,string.format(Tyc[2817],math.floor(kxb.shield+0.5)))
end
if kxb.fly>0 then
table.insert(lxb,string.format(Tyc[2818],math.floor(kxb.fly*100+0.5)))
