function cb.sim(rxb,sxb,txb)
if not I.sim or type(rxb.r._l)~=Tyc[1502]then
return nil
end
local uxb=tostring(rxb.r._r or(rxb.d..Tyc[1613]..rxb.choice))..(sxb and(Tyc[2352]..tostring(sxb))or Tyc[431])..(txb and Tyc[2819]or Tyc[431])
local vxb=cb.data()
local wxb=cb.fx(vxb,cb.roomCurse(rxb.r),sxb)
local xxb=O.teamSig()..Tyc[2820]..cb.fxText(wxb)..(I.killZone~=false and Tyc[2821]or Tyc[431])
local yxb=J.dg.sim[uxb]
if yxb and yxb.sig==xxb then
return not yxb.none and yxb or nil
end
local zxb={}
for Axb,Bxb in ipairs(N.equipped())do
table.insert(zxb,Bxb.u)
end
if#zxb==0 then
return nil
end
local Cxb=W.applyFx(W.info(W.slim(rxb.r._l),Tyc[1842],nil,cb.mod(rxb.r._l)),wxb)
if txb then
Cxb.zone=false
end
local Dxb=W.wave(Cxb,1,true)
if#Dxb==0 then
yxb={none=true,sig=xxb,at=os.time()}
else
local Exb=W.evaluate(Cxb,W.teamFrom(zxb,Cxb.map))
yxb={p=Exb.p,wave=Exb.wave,won=Exb.won,total=Cxb.total,margin=Exb.margin,sig=xxb,at=os.time(),zone=Cxb.zone~=false or nil}
end
J.dg.sim[uxb]=yxb
if M.count(J.dg.sim)>60 then
local Fxb,Gxb
for Hxb,Ixb in pairs(J.dg.sim)do
if not Gxb or(Ixb.at or 0)<Gxb then
Fxb,Gxb=Hxb,Ixb.at or 0
end
end
J.dg.sim[Fxb]=nil
end
j.saveSoon()
return not yxb.none and yxb or nil
end
function cb.winP(Jxb)
local Kxb=tostring(math.min(4,math.max(1,math.ceil(Jxb.d/5))))
local Lxb=J.dg.depth[Kxb]or{runs=0,wins=0}
local Mxb=M.clamp(0.95-0.015*Jxb.d,0.5,0.95)
local Nxb=((tonumber(Lxb.wins)or 0)+Mxb*2)/((tonumber(Lxb.runs)or 0)+2)
local Oxb,Pxb=pcall(cb.sim,Jxb)
if Oxb and Pxb and Pxb.p then
local Qxb,Rxb=pcall(W.styleP,Pxb,Pxb.zone==false and Tyc[2740]or(Pxb.zone and Tyc[2722]or nil))
Nxb=(Nxb*2+(Qxb and Rxb or Pxb.p))/3
end
return Nxb,Oxb and Pxb or nil
end
function cb.hopeless(Sxb)
return Sxb~=nil and Sxb.won==false and(tonumber(Sxb.p)or 1)<=0.05
end
function cb.stake(Txb)
local Uxb,Vxb,Wxb=cb.res(Txb)
return Vxb+2*Wxb
end
function cb.curseBar(Xxb,Yxb)
local Zxb=cb.stake(Xxb)
if Yxb>=15 or Zxb>=8 then
return 0.9,Tyc[2822],Zxb
end
if Yxb>=10 or Zxb>=4 then
return 0.6,Tyc[2823],Zxb
end
return 0.1,Tyc[2824],Zxb
end
function cb.blindCurse(_xb,ayb)
return cb.fxText(cb.fx(_xb,ayb))==cb.fxText(cb.fx(_xb))
end
function cb.curseOk(byb,cyb,dyb,eyb,fyb)
local gyb=tostring((cb.item(byb)or{}).name or byb)
local hyb,iyb,jyb=cb.curseBar(cyb,dyb)
if hyb>0.2 and cb.blindCurse(cyb,byb)then
return false,string.format(Tyc[2825],gyb,jyb)
end
local function kyb(lyb)
return lyb==nil or(tonumber(lyb.p)or 1)>=hyb
end
if eyb then
local myb,nyb=pcall(cb.sim,eyb,nil,true)
if myb and not kyb(nyb)then
return false,string.format(Tyc[2826],gyb,(iyb:gsub(Tyc[2827],Tyc[2828])),tostring(nyb.margin or Tyc[1740]))
end
end
if#fyb==0 then
return true
end
local oyb
for pyb,qyb in ipairs(fyb)do
local ryb,syb=pcall(cb.sim,qyb,byb,true)
if not ryb or kyb(syb)then
return true
end
if not oyb or(tonumber(syb.p)or 0)>(tonumber(oyb.p)or 0)then
oyb=syb
end
end
return false,string.format(Tyc[2829],gyb,iyb,tostring(oyb and oyb.margin or Tyc[1740]))
end
function cb.curseGate(tyb,uyb)
local vyb=cb.roomCurse(tyb.r)
if not vyb then
return true
end
return cb.curseOk(vyb,uyb,tyb.d,tyb,cb.after(uyb,tyb.choice))
end
function cb.payValue()
local wyb,xyb=0,0
for yyb,zyb in ipairs(J.dg.pay or{})do
if type(zyb.items)==Tyc[1502]then
local Ayb=tonumber(zyb.gems)or 0
for Byb,Cyb in pairs(zyb.items)do
if(tonumber(Cyb)or 0)>0 then
Ayb=Ayb+O.itemValue(Byb,Cyb)
end
end
wyb,xyb=wyb+Ayb,xyb+1
end
end
if xyb<5 then
return nil
end
return wyb/xyb*0.7
end
function cb.pick(Dyb)
local Eyb,Fyb=cb.curses(Dyb),cb.lives(Dyb)
local Gyb=cb.res(Dyb)
local Hyb=cb.rooms(Dyb)
local Iyb={}
for Jyb,Kyb in ipairs(Hyb)do
table.insert(Iyb,tostring(Kyb.r._r))
end
local Lyb=table.concat(Iyb,Tyc[2118])..string.format(Tyc[2830],Fyb,Gyb,Eyb,O.teamSig())
if cb._pick and cb._pick.sig==Lyb then
return cb._pick.x
end
local Myb,Nyb
for Oyb,Pyb in ipairs(Hyb)do
local Qyb=cb.roomValue(Pyb,Gyb)
local Ryb,Syb
for Tyb,Uyb in ipairs(cb.after(Dyb,Pyb.choice))do
local Vyb=cb.roomValue(Uyb,Gyb)
if not Ryb or Vyb>Ryb then
Ryb,Syb=Vyb,Uyb
end
end
local Wyb,Xyb=cb.winP(Pyb)
local Yyb=1-(1-Wyb)^math.max(1,Fyb)
local Zyb=Fyb>=3 and 1 or(Fyb==2 and 2 or 6)
Pyb.p,Pyb.sim,Pyb.value,Pyb.nextValue,Pyb.nextRoom=Wyb,Xyb,Qyb,Ryb or 0,Syb
Pyb.score=Yyb*(Qyb+0.6*(Ryb or 0))-(1-Wyb)*Zyb
local _yb,azb,bzb=pcall(cb.curseGate,Pyb,Dyb)
if _yb and not azb then
Pyb.blocked=bzb
end
if not Pyb.blocked and(not Myb or Pyb.score>Myb.score)then
Myb=Pyb
end
if not Nyb or Pyb.score>Nyb.score then
Nyb=Pyb
end
end
Myb=Myb or Nyb
cb._pick={sig=Lyb,x=Myb,rooms=Hyb}
return Myb
end
function cb.roomName(czb)
