function cb.offers(Bzb,Czb)
local Dzb={}
if type(Bzb)~=Tyc[1502]then
return Dzb
end
for Ezb,Fzb in pairs(Bzb)do
local Gzb,Hzb
if type(Fzb)==Tyc[1502]then
Gzb=Fzb.id or Fzb.item_id or Fzb.item
Hzb=tonumber(Fzb.cost)or tonumber(Fzb.price)
elseif type(Fzb)==Tyc[1504]then
Gzb=Fzb
elseif cb.item(Ezb)then
Gzb=Ezb
Hzb=tonumber(Fzb)
end
if type(Gzb)==Tyc[1504]and cb.item(Gzb)then
table.insert(Dzb,{key=Ezb,id=Gzb,cost=Hzb or tonumber(cb.item(Gzb).cost)or 0,bought=type(Fzb)==Tyc[1502]and(Fzb.bought or Fzb.sold or Fzb.purchased)or nil})
end
end
if#Dzb==0 and not Czb then
for Izb,Jzb in pairs(Bzb)do
if type(Jzb)==Tyc[1502]then
Dzb=cb.offers(Jzb,true)
if#Dzb>0 then
break
end
end
end
end
return Dzb
end
function cb.buy(Kzb)
local Lzb=cb.res(cb.data())
local Mzb={}
if J.dg.buyArg==Tyc[2686]then
Mzb={Kzb.id,Kzb.key}
else
Mzb={Kzb.key,Kzb.id}
end
if Mzb[1]==Mzb[2]then
Mzb[2]=nil
end
for Nzb,Ozb in ipairs(Mzb)do
local Pzb,Qzb=j.request(Tyc[2839],Tyc[2840],Ozb)
local Rzb=M.now()
while M.now()-Rzb<3 and cb.res(cb.data())>=Lzb do
task.wait(0.25)
end
if cb.res(cb.data())<Lzb then
J.dg.buyArg=(Ozb==Kzb.id and Kzb.id~=Kzb.key)and Tyc[2686]or Tyc[2841]
return true
end
if not Pzb then
break
end
end
return false
end
function cb.shopAhead(Szb)
for Tzb,Uzb in ipairs(cb.rooms(Szb))do
if Uzb.tags[cb.T.SHOP]then
return true
end
for Vzb,Wzb in ipairs(cb.after(Szb,Uzb.choice))do
if Wzb.tags[cb.T.SHOP]then
return true
end
end
end
return false
end
cb.LUCK_RESERVE=500
cb.MIN_WORTH=0.02
cb.TOP_WORTH=0.08
function cb.shop(Xzb,Yzb)
local Zzb=cb.cleared(Xzb)
local _zb=cb.res(Xzb)
local aAb=1+0.1*(cb.items(Xzb)._curse_shop or 0)
local bAb=cb.shopAhead(Xzb)and math.ceil(cb.LUCK_RESERVE*aAb)or 0
local cAb={}
local dAb,eAb={},0
for fAb,gAb in ipairs(cb.offers(Yzb and Yzb.data))do
gAb.cost=math.ceil(gAb.cost*aAb)
table.insert(dAb,tostring(cb.item(gAb.id).name or gAb.id))
if not gAb.bought and not cb.isCurse(gAb.id)then
gAb.luck=tonumber(cb.item(gAb.id).luck_increase)~=nil
gAb.v=cb.itemValue(gAb.id,Xzb)
if not gAb.luck and gAb.v/math.max(1,gAb.cost)<cb.MIN_WORTH then
eAb=eAb+1
elseif gAb.v>0 and(gAb.luck or Zzb>=10 or gAb.v/math.max(1,gAb.cost)>=cb.TOP_WORTH)then
table.insert(cAb,gAb)
end
end
end
table.sort(cAb,function(hAb,iAb)
if hAb.luck~=iAb.luck then
return hAb.luck
end
return hAb.v/math.max(1,hAb.cost)>iAb.v/math.max(1,iAb.cost)
end)
local jAb,kAb,lAb={},0,0
for mAb,nAb in ipairs(cAb)do
if nAb.cost<=_zb-(nAb.luck and 0 or bAb)then
if cb.buy(nAb)then
_zb=cb.res(cb.data())
table.insert(jAb,string.format(Tyc[2842],tostring(cb.item(nAb.id).name or nAb.id),nAb.cost))
end
elseif nAb.cost<=_zb then
lAb=lAb+1
else
kAb=kAb+1
end
end
cb.note(string.format(Tyc[2843],Zzb,#dAb>0 and table.concat(dAb,Tyc[1598])or Tyc[2844],#jAb>0 and(Tyc[2845]..table.concat(jAb,Tyc[1598]))or(Zzb<10 and Tyc[2846]or(lAb>0 and Tyc[2847]or Tyc[2848])),_zb,kAb>0 and string.format(Tyc[2849],kAb)or Tyc[431],lAb>0 and string.format(Tyc[2850],lAb,bAb)or Tyc[431],eAb>0 and string.format(Tyc[2851],eAb)or Tyc[431]))
j.request(Tyc[2852],Tyc[2853])
end
function cb.shrine(oAb,pAb)
local qAb=cb.offers(pAb and pAb.data)
local rAb,sAb=0,{}
local tAb
for uAb,vAb in ipairs(qAb)do
local wAb=cb.item(vAb.id)
table.insert(sAb,tostring(wAb and wAb.name or vAb.id))
if cb.isCurse(vAb.id)then
local xAb,yAb,zAb=pcall(cb.curseOk,vAb.id,oAb,cb.cleared(oAb)+1,nil,cb.rooms(oAb))
if xAb and not yAb then
tAb=zAb
end
else
rAb=rAb+cb.itemValue(vAb.id,oAb)
end
end
local AAb= #qAb>0 and rAb>0 and not tAb
if AAb then
j.request(Tyc[2854],Tyc[2855])
else
j.request(Tyc[2852],Tyc[2853])
end
cb.note(string.format(Tyc[2856],#sAb>0 and table.concat(sAb,Tyc[1598])or Tyc[2844],AAb and Tyc[2857]or(tAb and(Tyc[2858]..tAb)or Tyc[2859])))
end
function cb.wallet()
local BAb=H.session()and H.session().profile_data or{}
local CAb=BAb.inventory or{}
local DAb={gems=tonumber(H.cur(Tyc[1562]))or 0,gold=tonumber(H.cur(Tyc[1564]))or 0,items={},units={},unique=0}
for EAb,FAb in pairs(CAb.normal_items or{})do
DAb.items[EAb]=tonumber(FAb)or 0
end
for GAb,HAb in pairs(BAb.collection and BAb.collection.owned_units or{})do
DAb.units[GAb]=HAb.unit_id
end
for IAb in pairs(CAb.unique_items or{})do
DAb.unique=DAb.unique+1
end
return DAb
end
function cb.walletDiff(JAb,KAb)
local LAb={}
if KAb.gems~=JAb.gems then
table.insert(LAb,string.format(Tyc[2860],KAb.gems-JAb.gems))
end
if KAb.gold~=JAb.gold then
table.insert(LAb,string.format(Tyc[2861],KAb.gold-JAb.gold))
end
for MAb,NAb in pairs(KAb.items)do
if NAb~=(JAb.items[MAb]or 0)then
table.insert(LAb,string.format(Tyc[2862],NAb-(JAb.items[MAb]or 0),tostring(MAb)))
end
end
for OAb,PAb in pairs(KAb.units)do
if not JAb.units[OAb]then
table.insert(LAb,Tyc[2863]..N.name(PAb))
end
end
if KAb.unique~=JAb.unique then
table.insert(LAb,string.format(Tyc[2864],KAb.unique-JAb.unique))
end
return#LAb>0 and table.concat(LAb,Tyc[1598])or Tyc[2865]
end
function cb.openChests(QAb,RAb)
local SAb,TAb,UAb=cb.res(QAb)
local VAb=cb.lives(QAb)
local WAb=cb.cleared(QAb)
if not(RAb or WAb>=cb.ROOMS or VAb<=1)then
cb.note(string.format(Tyc[2866],WAb,TAb,UAb,cb.luck(QAb)))
j.request(Tyc[2852],Tyc[2853])
return
end
local XAb,YAb,ZAb=0,0,0
local _Ab=tonumber(H.cur(Tyc[1562]))or 0
local aBb=cb.wallet()
for bBb=1,TAb+UAb+4 do
local cBb,dBb,eBb=cb.res(cb.data())
if dBb+eBb<=0 or ZAb>=2 then
break
end
local fBb,gBb
if dBb>0 then
fBb,gBb=j.request(Tyc[2867],Tyc[2868])
else
fBb,gBb=j.request(Tyc[2867],Tyc[2868],true)
end
if fBb and gBb~=nil then
j.log(1,Tyc[2836],Tyc[2869]..(type(gBb)==Tyc[1502]and M.json(M.plain(gBb)):sub(1,300)or tostring(gBb)))
end
local hBb=M.now()
while M.now()-hBb<4 do
local iBb,jBb,kBb=cb.res(cb.data())
if jBb<dBb or kBb<eBb then
break
end
task.wait(0.25)
end
local lBb,mBb,nBb=cb.res(cb.data())
if mBb<dBb then
XAb=XAb+(dBb-mBb)
ZAb=0
elseif nBb<eBb then
YAb=YAb+(eBb-nBb)
ZAb=0
else
ZAb=ZAb+1
end
task.wait(1)
if mBb<dBb or nBb<eBb then
local oBb=cb.wallet()
local pBb=cb.walletDiff(aBb,oBb)
j.log(1,Tyc[2836],(nBb<eBb and Tyc[2870]or Tyc[2869])..pBb)
J.dg.pay=J.dg.pay or{}
local qBb={}
for rBb,sBb in pairs(oBb.items)do
if sBb~=(aBb.items[rBb]or 0)then
qBb[rBb]=sBb-(aBb.items[rBb]or 0)
