function Q.buildPath()
Q.samples={}
local eEb=H.PATH and H.PATH.PATH_CACHE and H.PATH.PATH_CACHE[workspace._BASES.pve]
if not eEb then
return
end
for fEb,gEb in pairs(eEb)do
if not(H.PATH.HIDDEN_MOCK_LANES and H.PATH.HIDDEN_MOCK_LANES[fEb.Name])then
local hEb={}
for iEb,jEb in ipairs(gEb.points or{})do
table.insert(hEb,jEb.part.Position)
end
local kEb=0
for lEb=2,#hEb do
kEb=kEb+(hEb[lEb]-hEb[lEb-1]).Magnitude
end
local mEb=0
for nEb=2,#hEb do
local oEb,pEb=hEb[nEb-1],hEb[nEb]
local qEb=(pEb-oEb).Magnitude
local rEb=math.max(1,math.floor(qEb/2))
for sEb=0,rEb-1 do
local tEb=oEb:Lerp(pEb,sEb/rEb)
table.insert(Q.samples,{pos=tEb,prog=(mEb+qEb*sEb/rEb)/math.max(1,kEb),lane=fEb.Name})
end
mEb=mEb+qEb
end
if hEb[#hEb]then
table.insert(Q.samples,{pos=hEb[#hEb],prog=1,lane=fEb.Name})
end
end
end
Q.laneCut,Q.laneWant,Q.laneFirst=nil,nil,nil
local uEb=tonumber(Q.ld and Q.ld._portal_lanes)
local vEb=W.laneList(Q.samples)
if uEb and uEb>=1 and vEb and#vEb>uEb then
Q.laneWant=uEb
end
Q.laneTotal=vEb and#vEb or 1
Q.countLanes()
end
function Q.countLanes()
local wEb,xEb,yEb={},0,0
for zEb,AEb in ipairs(Q.samples)do
local BEb=tostring(AEb.lane)
if not wEb[BEb]then
xEb=xEb+1
end
wEb[BEb]=(wEb[BEb]or 0)+1
yEb=yEb+1
end
Q.laneCount={n=xEb,by=wEb,avg=xEb>0 and yEb/xEb or 1}
end
function Q.portalLanes()
if not Q.laneWant or Q.laneCut then
return true
