if kHb.Magnitude<0.01 then
kHb=Vector3 .new(1,0,0)
end
kHb=kHb.Unit
local lHb=Vector3 .new(-kHb.Z,0,kHb.X)
for mHb,nHb in ipairs({3,4.5,6,8,10.5,13.5,17})do
for oHb,pHb in ipairs({1,-1})do
local qHb=iHb.pos+lHb*nHb*pHb
local rHb=string.format(Tyc[2979],math.floor(qHb.X/1.5),math.floor(qHb.Z/1.5))
if not gHb[rHb]then
gHb[rHb]=true
