function Q.coverage(sHb,tHb)
local uHb={}
for vHb,wHb in ipairs(sHb)do
local xHb=wHb._stats
if not N.isFarm(xHb.id.Value)and xHb:FindFirstChild(Tyc[1639])then
table.insert(uHb,{p=M.flat(wHb:GetPivot().Position),r=xHb.range.Value*(N.SUMMONER[xHb.id.Value]and N.SUMMONER[xHb.id.Value].reach or 1),air=Q.canAir(wHb)})
end
end
local yHb,zHb=0,0
if#uHb>0 then
for AHb,BHb in ipairs(Q.samples)do
if BHb.prog>zHb then
local CHb=M.flat(BHb.pos)
for DHb,EHb in ipairs(uHb)do
if(CHb-EHb.p).Magnitude<=EHb.r then
if BHb.prog>yHb then
yHb=BHb.prog
end
if EHb.air then
zHb=BHb.prog
break
end
end
end
end
end
end
local FHb,GHb={},Q.laneCount
if GHb and GHb.n>=2 and#uHb>0 then
local HHb={}
for IHb,JHb in ipairs(Q.samples)do
local KHb=M.flat(JHb.pos)
for LHb,MHb in ipairs(uHb)do
if(KHb-MHb.p).Magnitude<=MHb.r then
local NHb=tostring(JHb.lane)
HHb[NHb]=(HHb[NHb]or 0)+1
if JHb.prog>(FHb[NHb]or 0)then
FHb[NHb]=JHb.prog
end
break
end
end
end
local OHb,PHb={},0
for QHb,RHb in pairs(GHb.by)do
OHb[QHb]=(HHb[QHb]or 0)/math.max(1,RHb)
PHb=math.max(PHb,OHb[QHb])
end
Q.laneW={}
for SHb,THb in pairs(GHb.by)do
Q.laneW[SHb]=(GHb.avg/math.max(1,THb))*(1+1.5*(PHb>0 and(1-OHb[SHb]/PHb)or 0))
end
Q.laneFrac=OHb
else
Q.laneW,Q.laneFrac=nil,nil
end
local UHb,VHb,WHb
if#uHb>0 then
for XHb,YHb in ipairs(tHb)do
local ZHb=(Q.laneW and YHb.lane and FHb[YHb.lane])or yHb
if YHb.hp>0 and YHb.prog>ZHb+0.02 and YHb.prog>(UHb or 0)then
UHb,WHb=YHb.prog,Q.laneW and YHb.lane or nil
end
if YHb.hp>0 and YHb.fly and YHb.prog>zHb+0.02 then
VHb=true
end
end
end
local _Hb= #uHb>0 and(Q.pressure or 0)>=yHb-0.08
return{covEnd=yHb,airEnd=zHb,leak=UHb,leakLane=WHb,covL=FHb,airLeak=VHb,push=_Hb,units= #uHb}
end
function Q.needLastLine(aIb)
