N._airFrom={}
function N.airFrom(oIb)
local pIb=N._airFrom[oIb]
if pIb~=nil then
return pIb or nil
end
local qIb=H.Units[oIb]
if qIb and(qIb.hill_unit or qIb.hybrid_placement or N.SUMMONER[oIb])then
N._airFrom[oIb]=0
