for aSb,bSb in pairs(Q.helperDealt)do
if bSb.owner==Q.trialId then
_Rb=_Rb+bSb.v
end
end
table.insert(Q.trialTrace,string.format(Tyc[3039],PRb,ORb-(Q.startT or ORb),QRb,table.concat(SRb,Tyc[2118]),URb,TRb+_Rb,#(Q.enemies or{}),Q.hpAliveRaw or 0,Q.waveMax[PRb-1]or 0,Q.teamDps or 0))
end
