local cSb=workspace:FindFirstChild(Tyc[3040])
if cSb and PRb>0 then
MRb.timer[tostring(PRb)]=math.max(MRb.timer[tostring(PRb)]or 0,tonumber(cSb.Value)or 0)
end
local dSb=QRb-(Q.lastMoneyR or QRb)
Q.lastMoneyR=QRb
Q.incomeLog=Q.incomeLog or{}
if dSb>0 then
table.insert(Q.incomeLog,{t=ORb,y=dSb})
end
while Q.incomeLog[1]and ORb-Q.incomeLog[1].t>30 do
table.remove(Q.incomeLog,1)
end
local eSb=0
for fSb,gSb in ipairs(Q.incomeLog)do
eSb=eSb+gSb.y
end
local hSb=math.min(30,ORb-(Q.startT or ORb))
Q.incomeRate=hSb>=8 and eSb/hSb or nil
for iSb,jSb in ipairs(Q.enemies)do
