local lSb=Q.track[kSb]
if not lSb then
local mSb=kSb._stats
local nSb=kSb:FindFirstChildOfClass(Tyc[2967])
local oSb=NRb.cfgById[mSb.id.Value]
local pSb=oSb and W.baseStats(NRb,oSb)
if nSb and pSb and PRb>0 then
local qSb=pSb*NRb.hpRaw*W.waveScale(NRb,PRb,NRb.list[PRb])
if qSb>0 and nSb.MaxHealth>0 then
table.insert(MRb.hp,nSb.MaxHealth/qSb)
end
end
Q.track[kSb]={t=ORb,p=jSb.prog,sp=(mSb:FindFirstChild(Tyc[3041])and tonumber(mSb.speed.Value))or 1}
if PRb>0 then
