return 0
end
local OVb=0
for PVb,QVb in ipairs(Q.mine or{})do
local RVb=QVb._stats
local SVb=N.rows(RVb.id.Value)
local TVb=SVb and SVb[math.min(RVb.upgrade.Value,SVb.max)]
local UVb=TVb and TVb.atk and N.attackInfo(TVb.atk,TVb.range)
if UVb and((UVb.stun or 0)>0 or(UVb.slowTime or 0)>0)then
OVb=OVb+1
end
end
local VVb,WVb=W.mask(Q.info.map,N.range(LVb.u,0)*(Q.info.rangeScale or 1)),0
for XVb=1,W.BINS do
if VVb[XVb]then
WVb=WVb+1
end
end
