function Q.buffGain(_Vb)
local aWb=N.allyBuff(_Vb.id)
if not aWb then
return 0
end
local bWb=Q.buffShort(aWb)
local cWb=J.stack[aWb.attack]
local dWb=cWb and cWb.stacks and(cWb.cap or 1)or nil
local eWb,fWb=pcall(N.range,_Vb.u,0)
fWb=(eWb and tonumber(fWb)or 15)*((Q.info and tonumber(Q.info.rangeScale))or 1)
local gWb=dWb and I.community and tonumber(aWb.time)and tonumber(aWb.cd)
local function hWb(iWb,jWb)
local kWb=math.floor(iWb*aWb.time/math.max(1,aWb.cd)+0.001)
return math.min(dWb,(1+jWb)^kWb-1)
end
local lWb=0
for mWb,nWb in ipairs(bWb)do
local oWb=0
for pWb,qWb in ipairs(bWb)do
if(qWb.pos-nWb.pos).Magnitude<=fWb then
local rWb=aWb.types[qWb.base]
local sWb=rWb*aWb.uptime
if gWb then
local tWb,uWb=hWb(qWb.n,rWb),qWb.n+1
while uWb<qWb.n+6 and hWb(uWb,rWb)<=tWb+0.001 do
uWb=uWb+1
end
sWb=math.max(0,(hWb(uWb,rWb)-tWb)/(uWb-qWb.n))
elseif dWb then
sWb=math.max(0,math.min(dWb,(qWb.n+1)*rWb*aWb.uptime)-math.min(dWb,qWb.n*rWb*aWb.uptime))
end
oWb=oWb+qWb.dps*sWb
end
end
lWb=math.max(lWb,oWb)
end
return lWb*(gWb and 1 or 0.7)
end
